// Rule catalogue and per-pillar adapter. Vendor rules are a published conventional set, not Wenzhen official rules.
const SHENSHA_RULES={"天乙": {"name": "天乙贵人", "basis": "以年干、日干查目标地支", "icon": "✺"}, "太极": {"name": "太极贵人", "basis": "以年干、日干查目标地支", "icon": "☯"}, "天德": {"name": "天德贵人", "basis": "以月支查目标天干或地支", "icon": "✧"}, "月德": {"name": "月德贵人", "basis": "以月支查目标天干或地支", "icon": "☽"}, "德秀": {"name": "德秀贵人", "basis": "以月令与命局天干组合查", "icon": "❋"}, "天德合": {"name": "天德合", "basis": "以月支查目标天干或地支", "icon": "⟐"}, "月德合": {"name": "月德合", "basis": "以月支查目标天干或地支", "icon": "◉"}, "福星": {"name": "福星贵人", "basis": "以年干、日干查目标地支", "icon": "✶"}, "文昌": {"name": "文昌贵人", "basis": "以年干、日干查目标地支", "icon": "▤"}, "学堂": {"name": "学堂", "basis": "以年柱纳音查目标干支", "icon": "⌘"}, "词馆": {"name": "词馆", "basis": "以年柱纳音查目标干支", "icon": "▥"}, "魁罡": {"name": "魁罡贵人", "basis": "以完整日柱查", "icon": "✥"}, "国印": {"name": "国印贵人", "basis": "以年干、日干查目标地支", "icon": "⬡"}, "驿马": {"name": "驿马", "basis": "以年支、日支查目标地支", "icon": "⌁"}, "华盖": {"name": "华盖", "basis": "以年支、日支查目标地支", "icon": "♧"}, "将星": {"name": "将星", "basis": "以年支、日支查目标地支", "icon": "⚑"}, "金舆": {"name": "金舆", "basis": "以年干、日干查目标地支", "icon": "◇"}, "金神": {"name": "金神", "basis": "以日柱或时柱干支查", "icon": "✴"}, "五鬼": {"name": "五鬼", "basis": "以月支查目标天干或地支", "icon": "⊙"}, "天医": {"name": "天医", "basis": "以月支查目标天干或地支", "icon": "✚"}, "禄神": {"name": "禄神", "basis": "以日干查目标地支", "icon": "⊚"}, "天赦": {"name": "天赦", "basis": "以月份季节查日柱", "icon": "☀"}, "红鸾": {"name": "红鸾", "basis": "以年支查目标地支", "icon": "❀"}, "天喜": {"name": "天喜", "basis": "以年支查目标地支", "icon": "✿"}, "流霞": {"name": "流霞", "basis": "以日干查目标地支", "icon": "≈"}, "红艳": {"name": "红艳煞", "basis": "以日干查目标地支", "icon": "❃"}, "天罗": {"name": "天罗", "basis": "以年支、日支查目标地支", "icon": "⌒"}, "地网": {"name": "地网", "basis": "以年支、日支查目标地支", "icon": "⌣"}, "羊刃": {"name": "羊刃", "basis": "以日干查目标地支", "icon": "⚔"}, "飞刃": {"name": "飞刃", "basis": "以日干查目标地支", "icon": "⤨"}, "血刃": {"name": "血刃", "basis": "以月支查目标天干或地支", "icon": "⟡"}, "八专": {"name": "八专", "basis": "以完整日柱查", "icon": "▦"}, "九丑": {"name": "九丑", "basis": "以完整日柱查", "icon": "⌬"}, "劫煞": {"name": "劫煞", "basis": "以年支、日支查目标地支", "icon": "⟁"}, "灾煞": {"name": "灾煞", "basis": "以年支查目标地支", "icon": "⧫"}, "元辰": {"name": "元辰", "basis": "以年支、年干阴阳与传统排盘性别查", "icon": "⊗"}, "空亡": {"name": "空亡", "basis": "以年柱、日柱所属旬查其他柱地支", "icon": "◌"}, "童子": {"name": "童子煞", "basis": "以月份、年柱纳音查日支或时支", "icon": "♙"}, "天厨": {"name": "天厨贵人", "basis": "以年干、日干查目标地支", "icon": "♨"}, "孤辰": {"name": "孤辰", "basis": "以年支查目标地支", "icon": "◐"}, "寡宿": {"name": "寡宿", "basis": "以年支查目标地支", "icon": "◑"}, "亡神": {"name": "亡神", "basis": "以年支、日支查目标地支", "icon": "☍"}, "十恶大败": {"name": "十恶大败", "basis": "以完整日柱查", "icon": "✕"}, "桃花": {"name": "桃花", "basis": "以年支、日支查目标地支", "icon": "❁"}, "孤鸾": {"name": "孤鸾煞", "basis": "以完整日柱查", "icon": "⟠"}, "阴差阳错": {"name": "阴差阳错", "basis": "以完整日柱查", "icon": "☷"}, "四废": {"name": "四废", "basis": "以月份季节及日柱查", "icon": "⊞"}, "丧门": {"name": "丧门", "basis": "以年支查目标地支", "icon": "◒"}, "吊客": {"name": "吊客", "basis": "以年支查目标地支", "icon": "◓"}, "披麻": {"name": "披麻", "basis": "以年支查目标地支", "icon": "▧"}, "十灵": {"name": "十灵", "basis": "以完整日柱查", "icon": "✳"}};
const SHENSHA_BY_NAME=Object.fromEntries(Object.values(SHENSHA_RULES).map(v=>[v.name,v]));
function getOmenIcon(name){return SHENSHA_BY_NAME[name]?.icon||'✺'}
function computeOmenEntries(eight,gender=''){
 const ps=['Year','Month','Day','Time'],pairs=ps.map(p=>eight['get'+p]()),bazi=pairs.flatMap(p=>[...p]),hits=[];
 pairs.forEach((pair,k)=>{
  const raw=queryShenSha(pair,bazi,gender==='male',k+1,eight.getYearNaYin());
  [...new Set(raw)].forEach(short=>{
   if(short==='元辰'&&!gender)return;
   // These two vendor predicates are chart/day-wide; give them one honest carrier.
   if((short==='天赦'||short==='德秀')&&k!==2)return;
   const rule=SHENSHA_RULES[short],pillar=['年柱','月柱','日柱','时柱'][k];
   hits.push({id:'omen-'+short+'-'+k,name:rule.name,kind:'omen',pillar,rawName:short,basis:rule.basis,origin:pillar+' '+pair+' · '+rule.basis});
  });
 });return hits;
}
